const RETIRED_REPLACEMENT = new Map(
  Object.entries(RETIRED_NAMES).flatMap(([target, names]) => names.map((name) => [name, target]))
);

const MAX_NAME_IN_TEXT = 128;

/** Control characters as text, so a name can start no line of its own in a log. */
export function escapeControls(text) {
  return String(text).replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`);
}

/** A model name fit to put in a log or an error: under `routeAllModels` and in a pin, the request wrote it. */
export function safeName(name) {
  const text = String(name);
  return escapeControls(text.length > MAX_NAME_IN_TEXT ? `${text.slice(0, MAX_NAME_IN_TEXT)}...` : text);
}

/** Starts every `catalogNameWarning`, so a host can log each once rather than on every request. */
export const CATALOG_NAME_WARNING = "candidate name ";

/** Why a pool name is not routed on a row of its own, or `null` when it has one. */
export function catalogNameWarning(rawModel, models = DEFAULT_MODELS, aliases = MODEL_ALIASES) {
  const { key, source } = resolveModel(rawModel, models, aliases);
  if (source === "exact" || source === "alias") return null;
  const { name } = splitEffortSuffix(rawModel);
  const { tier } = resolveModelSpec(name, models, aliases).spec;
  const scored = source === "family" ? `scored as an estimate of ${key} (tier ${tier})` : `scored on the generic row (tier ${tier})`;
  const replacement = RETIRED_REPLACEMENT.get(name.split("/").pop().toLowerCase());
  return `${CATALOG_NAME_WARNING}${safeName(name)} is not in the catalog: ${scored}${replacement ? `; use ${replacement}` : ""}`;
}

/** The key of `rawModel` (`resolveModel`). */
export function canonicalModel(rawModel, aliases = MODEL_ALIASES, models = DEFAULT_MODELS) {
  if (!rawModel || typeof rawModel !== "string") return "";
  return resolveModel(rawModel, models, aliases).key;
}

/**
 * The speed-data view of `resolveModel`. `known` is false when the name has no row of its own (`family`, `unknown`), which
 * is what gives it the default responsiveness; `key` is then the family target or, with no row at all, the name as given,
 * as `allocator.py:canonical` returns it.
 */
export function resolveResponsivenessModelKey(
  rawModel,
  models = DEFAULT_MODELS,
  aliases = MODEL_ALIASES,
  curvesTable = EFFORT_CURVES,
  respTable = EFFORT_RESPONSIVENESS,
) {
  const raw = typeof rawModel === "string" ? rawModel.trim() : "";
  if (!raw) return { key: "", known: false, source: "unknown" };
  const { key, source } = resolveModel(raw, models, aliases, curvesTable, respTable);
  return { key: source === "unknown" ? raw : key, known: source === "exact" || source === "alias", source };
}

/**
 * `round(value, digits)` as Python does it: the double's exact value decides, and an exact tie goes to the even digit.
 * `Math.round(x * 1000)` rounds the product instead, and 0.7625 lands on the other side of it.
 */
export function pyRound(value, digits) {
  const number = Number(value);
  const scaled = Math.abs(number) * 10 ** digits;
  if (Math.abs(scaled - Math.floor(scaled) - 0.5) > 1e-6) return Number(number.toFixed(digits)) + 0;
  const exact = number.toFixed(digits + 60);
  const cut = exact.indexOf(".") + 1 + digits;
  if (!/^50*$/.test(exact.slice(cut)) || Number(exact[cut - 1]) % 2 === 1) return Number(number.toFixed(digits)) + 0;
  return Number(exact.slice(0, cut)) + 0;
}

const FAMILY_TIER_SHRINK = 0.3;
const FAMILY_VECTOR_SHRINK = 0.9;
const ESTIMATED_USD_PER_HOUR = 3.0;
const SMALL_NAME_RE = /(?:^|[-_.])(flash|lite|mini|nano|air|small|tiny|haiku|luna)(?:$|[-_.])/i;

const familySpecs = new WeakMap();

/** A family match has not verified the version or size: the target row shrunk, without its speed data (`auto_bundles.py:_shrink`). */
function familySpec(row) {
  let spec = familySpecs.get(row);
  if (spec) return spec;
  const {
    responsiveness: _speed,
    responsiveness_status: _status,
    speed_metrics: _metrics,
    disabled_by_default: _hidden,
    ...kept
  } = row;
  spec = { ...kept, score_estimated: "family", usd_per_hour: ESTIMATED_USD_PER_HOUR, usd_estimated: true };
  if (typeof spec.tier === "number") {
    spec.tier = pyRound(Math.max(1.0, spec.tier - FAMILY_TIER_SHRINK), 2);
  }
  for (const block of ["capabilities", "subjective"]) {
    if (spec[block] && typeof spec[block] === "object") {
      spec[block] = Object.fromEntries(
        Object.entries(spec[block]).map(([k, v]) => [
          k,
          typeof v === "number" ? pyRound(v * FAMILY_VECTOR_SHRINK, 3) : v,
        ])
      );
    }
  }
  if (spec.visual !== false && typeof spec.capabilities?.visual === "number") {
    spec.visual = spec.capabilities.visual;
  }
  familySpecs.set(row, spec);
  return spec;
}

const UNMEASURED_EFFORTS = ["low", "medium", "high"];
const GENERIC_SPEC = { ...UNMEASURED_MODELS.generic, efforts: UNMEASURED_EFFORTS, score_estimated: "unmeasured" };
const SMALL_SPEC = {
  ...UNMEASURED_MODELS.small,
  efforts: UNMEASURED_EFFORTS,
  score_estimated: "unmeasured",
  usd_per_hour: ESTIMATED_USD_PER_HOUR,
  usd_estimated: true,
};

/**
 * The row a name scores on: its own for `exact`/`alias`; for `family` the target row shrunk, or the small default when a
 * small-size name lands on a target that is not small (`auto_bundles.py:default_profile`); for `unknown` the generic default
 * (`allocator.py:model_spec`).
 */
export function resolveModelSpec(rawModel, models = DEFAULT_MODELS, aliases = MODEL_ALIASES) {
  const { key, source } = resolveModel(rawModel, models, aliases);
  const row = models?.[key] || DEFAULT_MODELS[key];
  const leaf = splitEffortSuffix(rawModel).name.split("/").pop();
  if (source === "exact" || source === "alias") return { canonical: key, spec: row, source };
  if (source === "family") {
    const small = SMALL_NAME_RE.test(leaf) && !SMALL_NAME_RE.test(key);
    return { canonical: key, spec: small ? SMALL_SPEC : familySpec(row), source };
  }
  return { canonical: key || "unknown", spec: GENERIC_SPEC, source };
}
